:root { font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; padding: 40px 16px; color: #ffffff; background: linear-gradient(135deg, #2563eb, #7c3aed); }
.weather { max-width: 680px; margin: 0 auto; }
.weather h1 { margin: 0 0 24px; text-align: center; }
#weather-form label { display: block; margin-bottom: 8px; font-weight: 700; }
#weather-form > div { display: flex; gap: 8px; }
input, button { min-height: 46px; padding: 12px 14px; border: 0; border-radius: 10px; font: inherit; }
input { flex: 1; min-width: 0; }
button { color: #ffffff; background: #0f172a; font-weight: 800; cursor: pointer; }
input:focus-visible, button:focus-visible { outline: 3px solid #fde68a; outline-offset: 3px; }
#weather-status { min-height: 24px; color: #fef3c7; }
#weather-result { padding: clamp(24px, 6vw, 36px); border: 1px solid rgba(255,255,255,.2); border-radius: 22px; background: rgba(255,255,255,.14); backdrop-filter: blur(12px); }
#city-name { margin: 0; }
.current { display: flex; align-items: center; gap: 14px; }
#weather-icon { font-size: 4rem; }
.current strong { font-size: clamp(3.5rem, 14vw, 5rem); font-weight: 300; }
.forecast { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.28); }
.forecast article { padding: 12px 5px; border-radius: 12px; background: rgba(255,255,255,.12); text-align: center; }
.forecast span { display: block; margin: 6px 0; font-size: 1.5rem; }
@media (max-width: 560px) { #weather-form > div { flex-direction: column; } .forecast { grid-template-columns: repeat(2, 1fr); } }

const weatherTypes = [{ icon: '☀️', text: '晴' }, { icon: '⛅', text: '多云' }, { icon: '☁️', text: '阴' }, { icon: '🌧️', text: '小雨' }, { icon: '⛈️', text: '雷阵雨' }];
const result = document.querySelector('#weather-result');
const status = document.querySelector('#weather-status');

function mockWeather(seed) {
  let hash = 0;
  for (const character of seed) hash = (hash * 31 + character.charCodeAt(0)) & 0xffffff;
  const next = maximum => { hash = (hash * 9301 + 49297) % 233280; return Math.floor(hash / 233280 * maximum); };
  return { type: weatherTypes[next(weatherTypes.length)], temperature: 15 + next(18), humidity: 40 + next(50), wind: 2 + next(20) };
}

function createForecast(city) {
  const container = document.querySelector('#forecast');
  container.replaceChildren();
  ['明天', '后天', '第 3 天', '第 4 天', '第 5 天'].forEach((day, index) => {
    const data = mockWeather(city + index);
    const card = document.createElement('article');
    const title = document.createElement('strong');
    const icon = document.createElement('span');
    const temperature = document.createElement('small');
    title.textContent = day;
    icon.textContent = data.type.icon;
    icon.setAttribute('aria-label', data.type.text);
    temperature.textContent = data.temperature + '°';
    card.append(title, icon, temperature);
    container.append(card);
  });
}

document.querySelector('#weather-form').addEventListener('submit', event => {
  event.preventDefault();
  const city = document.querySelector('#city-input').value.trim();
  if (!city) return;
  const data = mockWeather(city);
  document.querySelector('#city-name').textContent = city;
  document.querySelector('#weather-icon').textContent = data.type.icon;
  document.querySelector('#temperature').textContent = data.temperature;
  document.querySelector('#description').textContent = data.type.text;
  document.querySelector('#humidity').textContent = data.humidity;
  document.querySelector('#wind').textContent = data.wind;
  createForecast(city);
  result.hidden = false;
  status.textContent = '已展示 ' + city + ' 的模拟天气数据';
});
